import{_ as t,o,c as n,aa as a}from"./chunks/framework.BAs_AphD.js";const i="/buildary-help-preview/media/en/diary/en_m_off_zaznam.png",f=JSON.parse('{"title":"Offline Mode","description":"","frontmatter":{"title":"Offline Mode","wiki":"en:diary:m_offline"},"headers":[],"relativePath":"en/diary/m_offline.md","filePath":"en/diary/m_offline.md","lastUpdated":1794388980000}'),r={name:"en/diary/m_offline.md"};function s(l,e,d,c,h,p){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="offline-mode" tabindex="-1">Offline Mode <a class="header-anchor" href="#offline-mode" aria-label="Permalink to &quot;Offline Mode&quot;">​</a></h1><figure class="shot" style="--w:350px;"><img src="'+i+'" alt="" width="300" loading="lazy"></figure><p>If sufficiently reliable data services are not available on a project site, or there is no data connection at all, working online becomes slower or completely impossible.</p><p><strong>In Offline Mode, you can create new records</strong> or edit existing ones, although with certain limitations. <strong>All changes are saved on the mobile device and remain there until the data is synchronized with the server.</strong> We recommend synchronizing data as frequently as possible so that the latest data is also available to other Authorized Persons. Once a day is the recommended minimum.</p><p>Working in Offline Mode has both advantages and disadvantages. Independence from a data connection and faster operation are balanced by outdated information on the server, which can lead to conflicts between records. It is also important to keep in mind that some services and functions are not available offline, such as loading weather data, using AI (artificial intelligence) to generate records, changing the status of a day, responding to a record, signing records, etc.</p><p><strong>Offline Mode is activated automatically</strong> when the app is launched without a data connection, <strong>or manually</strong> through the <strong>App Menu</strong> in the Control Panel. The same menu can be used to switch back to Online Mode.</p><p>Offline Mode is indicated by the app header turning red.</p><p><strong>Records</strong> created in Offline Mode are indicated by a <strong>red marker on the right side of the record</strong>. This marker is displayed only for records that are stored on the mobile device but not yet on the server. It disappears after the data has been synchronized.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>For every new project, we recommend preparing all code lists, including drawings, and performing the initial synchronization to the mobile device while a reliable internet connection is available.</p></div><h2 id="data-synchronization" tabindex="-1">Data Synchronization <a class="header-anchor" href="#data-synchronization" aria-label="Permalink to &quot;Data Synchronization&quot;">​</a></h2><p>In a location with a reliable data connection, you need to <strong>connect to the internet</strong> (via Wi-Fi or mobile data) and <strong>open the Buildary app</strong>. If Offline Mode was enabled directly in the app, you need to switch to Online Mode via App Menu -&gt; select &quot;Work Online&quot;.</p><p>Synchronization is performed by <strong>reloading</strong>:</p><ol><li><strong>a page</strong> =&gt; if the change concerns, for example, only one section, navigate to that section. You can then <strong>swipe down on the screen</strong> to locally refresh the currently open page.</li><li><strong>a diary</strong> =&gt; selecting a diary from <strong>Diary History</strong> loads it and synchronizes all offline data recorded throughout the diary.</li><li><strong>a project</strong> =&gt; on the Diary History page, select &quot;<strong>Go to Project List</strong>&quot; and then <strong>load the selected project</strong>. If the project contains multiple diaries with offline data, this is the fastest way to synchronize all data for the entire project at once.</li><li><strong>multiple projects</strong> =&gt; on the same page as above, &quot;Select Project&quot;, <strong>press and hold to activate multi-select and select the projects</strong>. You can then use the option in the header to start a bulk synchronization.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p><strong>We recommend synchronizing data as frequently as possible so that the latest data is also available to other Authorized Persons. Once a day is the recommended minimum.</strong></p></div><p>The app is configured so that data stored on the server takes precedence over data entered from the mobile device during synchronization. This setting automatically filters out conflicting data, and such data will not be saved.</p>',15)])])}const m=t(r,[["render",s]]);export{f as __pageData,m as default};
